function marketplace(){return shell(page(
'<div><div class="eyebrow">Experience ecosystem</div><h1>Extend the creative vocabulary.</h1><p class="muted" style="max-width:720px">Recipes and themes are versioned capabilities, not arbitrary third-party code. Creators can publish reusable experiences without compromising the trusted runtime.</p></div>'+
'<div class="section"><div><h2>Featured recipes</h2><span class="muted small">Community + Invite originals</span></div></div><div class="grid g3">'+[['90s Romance','VHS · Timeline · Voice','12.4k uses','4.9'],['The Secret Letter','Reveal · Audio · RSVP','8.1k uses','4.8'],['Game Night','Quiz · Branching · Confetti','5.7k uses','4.9'],['Luxury Editorial','Scroll · Serif · Minimal','4.2k uses','4.7'],['Chat Story','Messages · Typing · Reveal','9.8k uses','4.9'],['Wedding Film','Timeline · Video · RSVP','18.2k uses','5.0']].map(x=>'<div class="card pad"><div class="experience-visual cinema" style="height:120px;border-radius:10px;margin-bottom:13px"><span>'+x[0]+'</span></div><h3>'+x[0]+'</h3><div class="muted small">'+x[1]+'</div><div class="row" style="margin-top:10px"><span class="tag">★ '+x[3]+'</span><span class="muted small">'+x[2]+'</span></div><button class="btn sm accent" style="margin-top:12px" onclick="useExperience(0)">Use recipe</button></div>').join('')+'</div>'+
'<div class="section"><h2>Creator program</h2></div><div class="card pad"><div class="grid g3"><div><b>Publish recipes</b><div class="muted small">Share your experience mechanics</div></div><div><b>Version safely</b><div class="muted small">Schema compatibility checks</div></div><div><b>Earn revenue</b><div class="muted small">Marketplace revenue sharing</div></div></div></div>'
),"Marketplace")}

function exports(){return shell(page(
'<div><div class="eyebrow">Export studio</div><h1>One experience. Every format.</h1><p class="muted">The ExperienceSpec is the source of truth. Export channels are generated from the same validated creative direction.</p></div>'+
'<div class="grid g3" style="margin-top:24px">'+[['Interactive website','Immutable static artifact','Ready','Publish'],['ZIP','Downloadable static site','Ready','Export'],['PDF / print','Invitation + QR layouts','Beta','Prepare'],['Social card','OpenGraph / share image','Ready','Export'],['Short video','30–60s experience trailer','Beta','Render'],['MP4 guest version','Linearized experience','Planned','Notify me']].map(x=>'<div class="card pad"><span class="status '+(x[2]==='Ready'?'live':'draft')+'">'+x[2]+'</span><h3 style="margin-top:10px">'+x[0]+'</h3><p class="muted small">'+x[1]+'</p><button class="btn sm" style="margin-top:10px" onclick="toast(\''+x[0]+' '+x[3].toLowerCase()+'\')">'+x[3]+'</button></div>').join('')+'</div>'+
'<div class="section"><h2>Localization</h2></div><div class="card pad"><div class="tags">'+['Romanian','English','Russian','French','German','Italian'].map((x,i)=>'<span class="tag">'+x+(i<3?' · translated':' · available')+'</span>').join('')+'</div><p class="muted small" style="margin-top:12px">AI translation preserves tone and intent, with source/translation provenance.</p><button class="btn sm accent" onclick="toast(\'Localization review opened\')">Review translations</button></div>'
),"Exports")}


function render(){
  if(S.onboard){$("app").innerHTML=onboard();return}
  const screens={home,create,experiences:experiencesPage,templates:templatesPage,invitations,campaigns:campaignsPage,assets,story:storyPage,interactions,analytics,distribution,settings,account,team,billing,marketplace,exports,editor,published};
  $("app").innerHTML=shellless(screens[S.screen]?screens[S.screen]():home());
  if(S.modal){const match=S.modal.match(/^experience:(\\d+)$/);if(match)$("app").insertAdjacentHTML("beforeend",experienceModal(Number(match[1])));else $("app").insertAdjacentHTML("beforeend",S.modal)}
}
function shellless(x){return x}
render();